+                    .withTargetProcessDefinitionKey(targetProcessDefinitionKey)
+                    .addMappingInstruction("taskA", "taskA2")
+                    .addMappingInstruction("taskB", "taskB2")
+                    .addMappingInstruction("taskC", "taskC2")
