+    filterProperty.set$In(values);
+    return this;
+  }
+
+  @Override
+  public BasicStringProperty in(final String... values) {
+    return in(CollectionUtil.toList(values));
+  }
+
+  @Override
+  public BasicStringProperty notIn(final List<String> values) {
