+    final var key = keyGenerator.nextKey();
+    final var record = toAsyncRequestRecord(scopeKey, command);
+    stateWriter.appendFollowUpEvent(key, AsyncRequestIntent.RECEIVED, record);
+    return new AsyncRequest(key, record);
+  }
+
