+    recordProp.getValue().wrap(record);
+  }
+
+  public AsyncRequestRecord getRecord() {
+    return recordProp.getValue();
+  }
+
+  public long getAsyncRequestKey() {
+    return asyncRequestKeyProperty.getValue();
+  }
