+      final ZeebeDb<ZbColumnFamilies> zeebeDb, final TransactionContext transactionContext) {
+    scopeKey = new DbLong();
+    asyncRequestMetadataKey = new AsyncRequestMetadataKey();
+    asyncRequestMetadataColumnFamily =
+        zeebeDb.createColumnFamily(
