+    buffer.putShort(offset, shortValue, ZB_DB_BYTE_ORDER);
+  }
+
+  public short getValue() {
+    return shortValue;
+  }
+
+  @Override
+  public String toString() {
+    return "DbShort{" + shortValue + '}';
+  }
+}

